"""Write or check the event catalogue (backend/docs/contracts/events.md) from the registered event types.

python manage.py event_catalogue            # CI: fail if the catalogue is out of date
python manage.py event_catalogue --write    # rewrite it after adding or changing an event type
"""

from pathlib import Path
from typing import Any

from django.conf import settings
from django.core.management.base import BaseCommand, CommandError, CommandParser

from platform_core import events

HEADER = """# Event catalogue

<!-- Generated by `python manage.py event_catalogue --write` from each module's events.py. Do not edit by hand. -->

Every event a module publishes through the outbox, with its payload contract. Rules
(D-041, `backend/platform_core/events.py`): names are `<thing>.<past-tense verb>`;
adding an optional field is compatible; any other change is a new version declared
next to the old one; payloads carry IDs and codes, never personal data; consumers
tolerate duplicates and out-of-order delivery.

Every event also carries: event ID, type, version, aggregate (type, ID, version),
organization (public UUID, the visibility scope), occurred-at time and correlation ID.
"""


def render() -> str:
    lines = [HEADER]
    by_module: dict[str, list[events.EventType]] = {}
    for event_type in events.registered():
        by_module.setdefault(event_type.module, []).append(event_type)
    if not by_module:
        lines.append("No event types are declared yet.\n")
    for module in sorted(by_module):
        lines += [f"## Published by `{module}`", "", "| Event | Version | Payload | Meaning |", "|---|---|---|---|"]
        for t in by_module[module]:
            payload = ", ".join(f"`{f}`" for f in t.fields)
            if t.optional:
                payload += ", optional " + ", ".join(f"`{f}`" for f in t.optional)
            lines.append(f"| `{t.name}` | {t.version} | {payload} | {t.description} |")
        lines.append("")
    return "\n".join(lines).rstrip("\n") + "\n"


class Command(BaseCommand):
    help = "Write or check the event catalogue in backend/docs/contracts/events.md."

    def add_arguments(self, parser: CommandParser) -> None:
        parser.add_argument("--write", action="store_true", help="Rewrite the catalogue.")
        parser.add_argument("--path", type=Path, default=None, help="Catalogue file (default: backend/docs/...).")

    def handle(self, *args: Any, **options: Any) -> None:
        path: Path = options["path"] or Path(settings.BASE_DIR) / "docs" / "contracts" / "events.md"
        content = render()
        current = path.read_text(encoding="utf-8").replace("\r\n", "\n") if path.exists() else None
        if current == content:
            self.stdout.write(self.style.SUCCESS("Event catalogue is up to date."))
            return
        if not options["write"]:
            raise CommandError("The event catalogue is out of date: run python manage.py event_catalogue --write")
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="\n")
        self.stdout.write(f"Rewrote {path.name}.")
